import { calculateBookingPrice } from "@/lib/pricing";

export type CardSlot = { label?: string; start: string; end: string };
export type PricedCardSlot = CardSlot & { price: number; hours: number };

const mins = (t: string) => Number(t.slice(0, 2)) * 60 + Number(t.slice(3, 5));

/**
 * The time cards a ground shows on the website. Once the admin has chosen cards, exactly those are shown.
 * Before that (older grounds) only slots the admin made by hand count — never the 1-hour slots generated by the hour editor.
 */
export function cardSlotsOf(g: any): CardSlot[] {
  if (Array.isArray(g.featuredSlots)) return [...g.featuredSlots].sort((a, b) => a.start.localeCompare(b.start));
  return (g.customSlots || [])
    .filter((s: any) => (s.label && s.label.trim()) || mins(s.end) - mins(s.start) >= 120)
    .map((s: any) => ({ label: s.label, start: s.start, end: s.end }))
    .sort((a: CardSlot, b: CardSlot) => a.start.localeCompare(b.start));
}

/** Cards with today's price on them. */
export function pricedCards(g: any, date: string): PricedCardSlot[] {
  return cardSlotsOf(g).map((c) => {
    let price = 0;
    try { price = calculateBookingPrice(g, date, c.start, c.end).subtotal; } catch {}
    return { ...c, price, hours: (mins(c.end) - mins(c.start)) / 60 };
  });
}

/** Link that opens the booking page with this card's hours already chosen. */
export function cardHref(groundId: string, c: CardSlot) {
  return `/portal/book?groundId=${groundId}&hour=${Number(c.start.slice(0, 2))}&until=${Math.ceil(mins(c.end) / 60)}`;
}

/** Which of the 24 hours a ground is open for booking (from its fixed slots, or opening → closing time). */
export function openHoursOf(v: { openingTime?: string; closingTime?: string; customSlots?: { start: string; end: string }[] }): boolean[] {
  const open = Array<boolean>(24).fill(false);
  if (v.customSlots && v.customSlots.length > 0) {
    for (const s of v.customSlots) {
      const a = mins(s.start); let b = mins(s.end); if (b <= a) b = 1440;
      for (let h = Math.floor(a / 60); h < Math.ceil(b / 60) && h < 24; h++) open[h] = true;
    }
  } else {
    const a = mins(v.openingTime || "00:00"); const b = mins(v.closingTime || "00:00");
    for (let h = Math.floor(a / 60); h < Math.ceil(b / 60) && h < 24; h++) open[h] = true;
  }
  return open;
}
